import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2

        if k >= 2**(n - 1):
            results.append("YES " + str(n - 1))
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
